document.addEventListener('DOMContentLoaded',()=>{const status=document.querySelector('#render-status');try{renderMathInElement(document.querySelector('main'),{delimiters:[{left:'$$',right:'$$',display:true},{left:'$',right:'$',display:false}],throwOnError:true});mermaid.initialize({startOnLoad:false,theme:'neutral',securityLevel:'strict'});mermaid.run({querySelector:'.mermaid'}).catch(()=>{status.textContent='流程图未渲染，仍可阅读源结构';});status.textContent='公式已排版 · 可离线阅读';}catch(e){status.textContent='公式排版失败，请查看下载资源';status.classList.add('error');}const input=document.querySelector('#score'),output=document.querySelector('#attention-output');function update(){const s=Number(input.value),b=Math.exp(s)/(1+Math.exp(s)),a=1-b;output.textContent=`s=${s.toFixed(1)}  权重=[${a.toFixed(3)}, ${b.toFixed(3)}]\n读取结果=[${(2*a).toFixed(3)}, ${(4*b).toFixed(3)}]`;}input.addEventListener('input',update);update();document.querySelector('#print').addEventListener('click',()=>window.print());});